window.EP = {"name": "ch10", "label": "एपिसोड 10", "en": "Dear God, Please Find Attached", "duration": 1141.11, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 14.71, "text": "चैप्टर टेन। डियर गॉड, प्लीज़ फ़ाइंड अटैच्ड"}, {"start": 15.26, "end": 16.81, "text": "डे इलेवन। चितई"}], "captions": [{"start": 18.36, "end": 21.65, "text": "ग्यारह मिनट में हम सामान बाँधकर बसंती में थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 21.65, "end": 25.52, "text": "मैंने चार लोगों को कभी इतनी तेज़ी से हिलते नहीं देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 25.52, "end": 29.09, "text": "और मैंने स्टूडेंट्स को लेक्चर हॉल छोड़ते देखा है,", "who": "", "voice": "narrator", "diary": false}, {"start": 29.09, "end": 30.92, "text": "जब घंटी जल्दी बज जाती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 31.37, "end": 36.17, "text": "इजा, सिर पर शॉल डाले, धूसर भोर में, हमें गाड़ी तक छोड़ने आईं,", "who": "", "voice": "narrator", "diary": false}, {"start": 36.17, "end": 40.27, "text": "और क्षितिज के हाथों में स्टील का एक टिफ़िन थमा दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 40.27, "end": 45.94, "text": "जैसे ही गब्बर ने इंजन स्टार्ट किया, क्षितिज पीछे की खिड़की से बाहर झुका,", "who": "", "voice": "narrator", "diary": false}, {"start": 45.94, "end": 50.03, "text": "और उनसे वो सवाल पूछा, जो उसने पिछली रात लिख लिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 50.48, "end": 51.01, "text": "इजा जी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 51.01, "end": 51.84, "text": "आपका मायका।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 51.84, "end": 52.75, "text": "कौन सा गाँव?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 53.2, "end": 55.15, "text": "वो पूछे जाने पर हैरान दिखीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 55.15, "end": 60.16, "text": "फिर वो वैसी दूर वाली मुस्कान मुस्कुराईं, जो लोगों के चेहरे पर तब आती है,", "who": "", "voice": "narrator", "diary": false}, {"start": 60.16, "end": 63.72, "text": "जब वो उस घर की बात करते हैं, जिसमें वो पैदा हुए थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 64.17, "end": 65.51, "text": "जोहार में, बेटा।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 65.51, "end": 66.27, "text": "बहुत ऊपर।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 66.27, "end": 67.87, "text": "मिलम के रास्ते में।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 67.87, "end": 70.81, "text": "अब वहाँ सर्दियों में कोई नहीं रहता।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 70.81, "end": 72.41, "text": "सब नीचे आ जाते हैं।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 72.86, "end": 75.71, "text": "और आपकी माँ ने वो गीत… गरम पत्थर वाला… कहाँ से सीखा था?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 76.16, "end": 77.08, "text": "मौसा जी से।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 77.28, "end": 80.32, "text": "इजा ने कंधे उचकाए, जैसे ये तो ज़ाहिर बात हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 80.52, "end": 84.08, "text": "मेरी मौसी ने एक गढ़वाली चरवाहे से शादी की थी।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 84.08, "end": 85.83, "text": "द्रोणागिरी की तरफ़ का।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 85.83, "end": 86.86, "text": "कुंदन नाम था।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 86.86, "end": 87.81, "text": "वही गाते थे।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 88.26, "end": 90.21, "text": "गब्बर ने इतनी ज़ोर से ब्रेक मारे,", "who": "", "voice": "narrator", "diary": false}, {"start": 90.21, "end": 92.58, "text": "कि हम सब अपनी आगे वाली सीटों से टकरा गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 93.03, "end": 95.45, "text": "वो ड्राइवर की सीट पर पूरे मुड़ गए,", "who": "", "voice": "narrator", "diary": false}, {"start": 95.45, "end": 98.29, "text": "और खिड़की से बाहर अपनी माँ को घूरने लगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 98.74, "end": 99.23, "text": "कुंदन?", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 99.23, "end": 101.29, "text": "इजा, आपने कभी बताया नहीं…", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 101.74, "end": 102.88, "text": "तूने कभी पूछा नहीं।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 103.08, "end": 104.84, "text": "इजा ने बिल्कुल वाजिब तरीक़े से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 105.04, "end": 107.36, "text": "तू तो बचपन में सिर्फ़ गाड़ियों की बात करता था।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 107.81, "end": 112.21, "text": "मैं आपको नहीं बताऊँगा, कि गब्बर के चेहरे ने क्या किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 112.21, "end": 116.69, "text": "वो एक ख़ुद्दार आदमी हैं, और वो ये किताब पढ़ने वाले हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 117.14, "end": 118.95, "text": "कुंदन मौसा अब नहीं रहे।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 119.15, "end": 123.55, "text": "इजा ने क्षितिज से आगे कहा, जिसका पेन निकल चुका था।", "who": "", "voice": "narrator", "diary": false}, {"start": 123.75, "end": 124.96, "text": "बहुत साल हुए।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 124.96, "end": 127.28, "text": "उनके बेटे की बहू है, धना।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 127.28, "end": 130.81, "text": "सर्दियों में गंगोलीहाट के पास रहती है।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 130.81, "end": 134.06, "text": "गर्मियों में जोहार वाले घर जाती है।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 134.06, "end": 137.78, "text": "पुराने घर में मौसा का सारा सामान रखा है।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 137.78, "end": 139.54, "text": "कोई हाथ नहीं लगाता।", "who": "इजा", "voice": "ija", "diary": false}, {"start": 139.99, "end": 143.35, "text": "फिर उन्होंने खिड़की से गब्बर का गाल थपथपाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 143.35, "end": 145.8, "text": "और उनसे धीरे गाड़ी चलाने को कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 145.8, "end": 149.54, "text": "उन्होंने शाओनी से कहा, कि चेहरे पर और हल्दी लगाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 149.54, "end": 150.99, "text": "उन्होंने मुझसे कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 150.99, "end": 154.58, "text": "कि मैं एक प्रोफ़ेसर के हिसाब से बहुत दुबला हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 154.58, "end": 157.94, "text": "और वो रास्ते से वापस अपने घर की तरफ़ चल दीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 158.39, "end": 160.71, "text": "हम रुकी हुई गाड़ी में ख़ामोश बैठे रहे।", "who": "", "voice": "narrator", "diary": false}, {"start": 161.16, "end": 161.63, "text": "जोहार।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 161.83, "end": 163.71, "text": "आख़िरकार गब्बर ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 163.71, "end": 165.34, "text": "उनकी आवाज़ अजीब थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 165.54, "end": 167.48, "text": "राजुला भी जोहार की थी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 167.48, "end": 168.45, "text": "शौका लड़की।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 168.45, "end": 169.25, "text": "जोहार की।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 169.25, "end": 170.66, "text": "सब यही कहते हैं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 171.36, "end": 172.8, "text": "राजुला के देश।", "who": "", "voice": "narrator", "diary": false}, {"start": 173.5, "end": 178.04, "text": "पीछे की सीट पर, क्षितिज ने आँखें बंद कीं, अपनी डायरी खोली,", "who": "", "voice": "narrator", "diary": false}, {"start": 178.04, "end": 182.65, "text": "कैपिटल्स में एक शब्द लिखा, और उसके नीचे तीन बार लाइन खींची।", "who": "", "voice": "narrator", "diary": false}, {"start": 183.35, "end": 183.83, "text": "जोहार।", "who": "", "voice": "narrator", "diary": false}, {"start": 185.33, "end": 186.47, "text": "हमें सोचना था।", "who": "", "voice": "narrator", "diary": false}, {"start": 186.47, "end": 190.29, "text": "हमें ऐसी जगह चाहिए थी, जिसकी रोहन उम्मीद न करे।", "who": "", "voice": "narrator", "diary": false}, {"start": 190.29, "end": 193.38, "text": "और, सच कहूँ, तो मुझे ऐसी जगह चाहिए थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 193.38, "end": 199.49, "text": "जहाँ मैं लैपटॉप वाले एक प्रोफ़ेसर से ज़्यादा ताक़तवर किसी से मदद माँग सकूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 199.94, "end": 201.99, "text": "तो हम एक देवता से शिकायत करने गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 202.44, "end": 208.64, "text": "चितई में गोलू देवता का मंदिर, अल्मोड़ा से कुछ किलोमीटर दूर, पेड़ों के एक झुरमुट में है,", "who": "", "voice": "narrator", "diary": false}, {"start": 208.64, "end": 210.56, "text": "एक ऐसे रास्ते के आख़िर में,", "who": "", "voice": "narrator", "diary": false}, {"start": 210.56, "end": 214.84, "text": "जिसके दोनों तरफ़ मिठाई की दुकानें और घंटियाँ बेचने वाले हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 214.84, "end": 217.05, "text": "आप उसे देखने से पहले सुनते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 217.75, "end": 218.55, "text": "घंटियाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 219.25, "end": 220.0, "text": "हज़ारों।", "who": "", "voice": "narrator", "diary": false}, {"start": 220.0, "end": 221.21, "text": "दसियों हज़ार।", "who": "", "voice": "narrator", "diary": false}, {"start": 221.21, "end": 224.66, "text": "हर शहतीर से, हर रेलिंग से, हर डाल से,", "who": "", "voice": "narrator", "diary": false}, {"start": 224.66, "end": 228.21, "text": "पेड़ों के बीच तनी हर तार से लटकती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 228.21, "end": 236.15, "text": "अँगूठे जितनी छोटी पीतल की घंटियाँ, और बाल्टी जितनी बड़ी घंटियाँ, पुरानी हरी पड़ चुकी,", "who": "", "voice": "narrator", "diary": false}, {"start": 236.15, "end": 240.44, "text": "और नई चमकती हुई, जिन्हें कुमाऊँ के हर कोने से,", "who": "", "voice": "narrator", "diary": false}, {"start": 240.44, "end": 245.02, "text": "और उससे भी बहुत दूर से आए लोगों ने यहाँ बाँधा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 245.02, "end": 249.87, "text": "जब हवा झुरमुट से गुज़रती है, तो सब एक साथ बोलती हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 249.87, "end": 253.42, "text": "धीरे से, जैसे कोई भीड़ फुसफुसा रही हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 253.87, "end": 256.39, "text": "और घंटियों के बीच में: काग़ज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 256.84, "end": 257.63, "text": "चिट्ठियाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 257.63, "end": 258.42, "text": "अर्ज़ियाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 258.42, "end": 259.37, "text": "स्टांप पेपर।", "who": "", "voice": "narrator", "diary": false}, {"start": 259.37, "end": 260.64, "text": "नोटबुक के पन्ने।", "who": "", "voice": "narrator", "diary": false}, {"start": 260.64, "end": 264.12, "text": "कुछ साफ़-सुथरी हिंदी में, कुछ अंग्रेज़ी में,", "who": "", "voice": "narrator", "diary": false}, {"start": 264.12, "end": 267.28, "text": "कुछ कुमाऊँनी में, कुछ काँपती पेंसिल में।", "who": "", "voice": "narrator", "diary": false}, {"start": 267.28, "end": 269.26, "text": "मोड़कर, लपेटकर, पिन करके,", "who": "", "voice": "narrator", "diary": false}, {"start": 269.26, "end": 273.54, "text": "लाल धागे से हर उस चीज़ पर बँधे हुए, जो उन्हें थाम सके।", "who": "", "voice": "narrator", "diary": false}, {"start": 273.99, "end": 278.06, "text": "गोलू देवता से, इंसाफ़ के देवता से, ऐसे बात की जाती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 278.06, "end": 279.57, "text": "आप उन्हें लिखते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 279.57, "end": 281.15, "text": "आप अपना केस रखते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 281.15, "end": 287.03, "text": "आप इंसाफ़ माँगते हैं: धोखेबाज़ मकान-मालिक के ख़िलाफ़, भ्रष्ट अफ़सर के ख़िलाफ़,", "who": "", "voice": "narrator", "diary": false}, {"start": 287.03, "end": 289.82, "text": "नाइंसाफ़ बॉस के ख़िलाफ़, किसी बीमारी,", "who": "", "voice": "narrator", "diary": false}, {"start": 289.82, "end": 292.54, "text": "खोए हुए बच्चे, खोई हुई नौकरी के लिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 292.54, "end": 294.88, "text": "और अगर आपकी मन्नत पूरी होती है,", "who": "", "voice": "narrator", "diary": false}, {"start": 294.88, "end": 297.44, "text": "तो आप वापस आकर एक घंटी बाँधते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 297.89, "end": 304.95, "text": "वही देवता, जिसके बारे में हमने पूरी रात गाना सुना था, वो लड़का, जिसे एक पत्थर से बदल दिया गया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 304.95, "end": 308.52, "text": "जो लकड़ी के घोड़े पर अपने पिता के महल में गया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 308.52, "end": 313.39, "text": "हिमालय का सबसे पुराना और सबसे व्यस्त कंप्लेंट डिपार्टमेंट चलाता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 313.84, "end": 316.39, "text": "मैं उन सारी घंटियों के बीच खड़ा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 316.39, "end": 318.65, "text": "और आपको सच बताऊँ: मैं हँस पड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 318.65, "end": 319.67, "text": "देवता पर नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 319.67, "end": 320.25, "text": "राहत से।", "who": "", "voice": "narrator", "diary": false}, {"start": 320.25, "end": 323.89, "text": "क्योंकि दस दिनों में पहली बार, मैं ऐसी जगह आया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 323.89, "end": 328.04, "text": "जहाँ कोई एक प्रोफ़ेसर से जवाबों की उम्मीद नहीं कर रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 328.49, "end": 329.8, "text": "मैंने अर्ज़ियाँ पढ़ीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 329.8, "end": 332.84, "text": "पढ़ने की इजाज़त है; वो वहीं खुले में लटकी रहती हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 332.84, "end": 336.11, "text": "और एक-एक करके, उन्होंने मेरा दिल थोड़ा-थोड़ा तोड़ दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 336.56, "end": 339.68, "text": "गोलू देवता, मेरे बेटे की नौकरी लगवा दो।", "who": "", "voice": "narrator", "diary": false}, {"start": 339.68, "end": 341.44, "text": "तीन साल से घर बैठा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 341.89, "end": 346.47, "text": "हे न्याय देवता, हमारे खेत पर पड़ोसी ने क़ब्ज़ा कर लिया है।", "who": "", "voice": "narrator", "diary": false}, {"start": 346.47, "end": 348.29, "text": "कोर्ट में दस साल हो गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 348.74, "end": 350.94, "text": "मेरी माँ का ऑपरेशन है चौदह तारीख़ को।", "who": "", "voice": "narrator", "diary": false}, {"start": 350.94, "end": 352.07, "text": "उन्हें ठीक कर देना।", "who": "", "voice": "narrator", "diary": false}, {"start": 352.52, "end": 354.63, "text": "मैं ये बैंगलोर से लिख रहा हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 354.63, "end": 359.06, "text": "जब मैं पैदा हुआ था, मेरी माँ ने यहाँ मेरे लिए एक घंटी बाँधी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 359.06, "end": 361.24, "text": "प्लीज़, मुझे जल्दी घर आने देना।", "who": "", "voice": "narrator", "diary": false}, {"start": 361.69, "end": 364.22, "text": "मैं एक रहस्य ढूँढने आया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 364.22, "end": 369.48, "text": "मुझे पूरी इंसानी मुसीबत का एक गाँव वाला नोटिसबोर्ड मिला।", "who": "", "voice": "narrator", "diary": false}, {"start": 369.48, "end": 370.33, "text": "नौकरियाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 370.33, "end": 370.89, "text": "ज़मीन।", "who": "", "voice": "narrator", "diary": false}, {"start": 370.89, "end": 371.55, "text": "बीमारी।", "who": "", "voice": "narrator", "diary": false}, {"start": 371.55, "end": 372.02, "text": "दूरी।", "who": "", "voice": "narrator", "diary": false}, {"start": 372.02, "end": 372.3, "text": "डर।", "who": "", "voice": "narrator", "diary": false}, {"start": 372.3, "end": 376.8, "text": "हर एक पर एक असली नाम लिखा था, किसी ऐसे इंसान का,", "who": "", "voice": "narrator", "diary": false}, {"start": 376.8, "end": 381.87, "text": "जो ये मानकर यहाँ तक चढ़ा था, कि कोई, कहीं, सुन रहा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 382.32, "end": 387.53, "text": "यही वो छुपा हुआ उत्तराखंड है, जिसे कोई पोस्टकार्ड पर नहीं छापता।", "who": "", "voice": "narrator", "diary": false}, {"start": 387.53, "end": 388.26, "text": "भूत नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 388.26, "end": 389.57, "text": "प्लूटोनियम नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 389.57, "end": 389.81, "text": "ये।", "who": "", "voice": "narrator", "diary": false}, {"start": 391.31, "end": 395.29, "text": "मैंने गेट की एक दुकान से स्टांप पेपर की एक शीट ख़रीदी।", "who": "", "voice": "narrator", "diary": false}, {"start": 395.29, "end": 397.06, "text": "मैं एक सीढ़ी पर बैठ गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 397.06, "end": 400.89, "text": "और मैंने अपनी अर्ज़ी लिखी, ढंग से, उसी फ़ॉर्मैट में,", "who": "", "voice": "narrator", "diary": false}, {"start": 400.89, "end": 405.31, "text": "जो मैं बारह साल से पढ़ा रहा हूँ, क्योंकि मैं जो हूँ, सो हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 405.76, "end": 411.09, "text": "टू, श्री गोलू देवता जी, न्याय के देवता, चितई, अल्मोड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 411.54, "end": 414.34, "text": "सब्जेक्ट: वन मिस्टर रोहन सहगल से प्रोटेक्शन,", "who": "", "voice": "narrator", "diary": false}, {"start": 414.34, "end": 418.72, "text": "और एक मिसिंग न्यूक्लियर डिवाइस के संबंध में असिस्टेंस हेतु रिक्वेस्ट।", "who": "", "voice": "narrator", "diary": false}, {"start": 419.42, "end": 420.86, "text": "रिस्पेक्टेड सर,", "who": "", "voice": "narrator", "diary": false}, {"start": 421.56, "end": 428.91, "text": "विद ड्यू रिस्पेक्ट, मैं ये कहना चाहता हूँ, कि मैं अहमदाबाद का एक प्रोफ़ेसर हूँ, और इस वक़्त आपके जूरिस्डिक्शन में,", "who": "", "voice": "narrator", "diary": false}, {"start": 428.91, "end": 430.65, "text": "एक ऐसे आदमी से भाग रहा हूँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 430.65, "end": 433.88, "text": "जो कुछ ऐसा खोदना चाहता है, जिसे दबा ही रहना चाहिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 433.88, "end": 436.2, "text": "उसके पास मेरी मम्मी का फ़ोन नंबर है।", "who": "", "voice": "narrator", "diary": false}, {"start": 436.2, "end": 438.84, "text": "उसने मेरी दोस्त के भाई को किडनैप किया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 438.84, "end": 440.58, "text": "कुछ देर के लिए, चाय के साथ।", "who": "", "voice": "narrator", "diary": false}, {"start": 440.58, "end": 443.74, "text": "उसने मलेथा में एक इक्यानवे साल के आदमी को धमकाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 443.74, "end": 445.1, "text": "काइंडली डू द नीडफ़ुल।", "who": "", "voice": "narrator", "diary": false}, {"start": 445.55, "end": 448.1, "text": "थैंकिंग यू इन एंटिसिपेशन।", "who": "", "voice": "narrator", "diary": false}, {"start": 448.1, "end": 451.47, "text": "योर्स फ़ेथफ़ुली, प्रोफ़ेसर पार्थ।", "who": "", "voice": "narrator", "diary": false}, {"start": 451.47, "end": 453.62, "text": "अननोन एंटिटी, फ़ीमेल?", "who": "", "voice": "narrator", "diary": false}, {"start": 454.07, "end": 457.58, "text": "मैंने उसे लपेटा, और लाल धागे से रेलिंग पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 457.58, "end": 461.85, "text": "चोरी हुई एक भैंस वाली अर्ज़ी के बग़ल में बाँध दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 461.85, "end": 466.79, "text": "फिर मैंने घंटियों के आगे सिर झुकाया, और हर शब्द दिल से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 467.24, "end": 468.27, "text": "तुम भी लिखो।", "who": "", "voice": "narrator", "diary": false}, {"start": 468.47, "end": 469.58, "text": "मैंने शाओनी से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 470.03, "end": 470.8, "text": "डेटा नहीं है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 471.0, "end": 471.88, "text": "उसने मुझसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 472.08, "end": 475.38, "text": "एक गॉड ऑफ़ जस्टिस का कंप्लेंट डिपार्टमेंट।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 475.38, "end": 476.56, "text": "रिस्पॉन्स टाइम?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 476.56, "end": 477.42, "text": "सक्सेस रेट?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 477.42, "end": 478.36, "text": "कोई एस-एल-ए?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 478.56, "end": 479.5, "text": "उसने सिर हिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 479.7, "end": 481.34, "text": "मैं प्रोफ़ेशनल हूँ, पार्थ।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 481.79, "end": 485.83, "text": "पाँच मिनट बाद, जब उसे लगा, कि हम सब घंटियाँ देख रहे हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 485.83, "end": 489.37, "text": "क्षितिज ने मुझे कोहनी मारी, और सिर से इशारा किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 489.82, "end": 493.78, "text": "रेलिंग के बिल्कुल दूसरे सिरे पर, शाओनी अकेली खड़ी थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 493.78, "end": 496.55, "text": "लोहे पर एक अकेला लाल धागा बाँधती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 496.55, "end": 497.75, "text": "कोई काग़ज़ नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 497.75, "end": 498.94, "text": "कोई अर्ज़ी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 498.94, "end": 502.23, "text": "बस धागा, तीन बार गाँठ लगाकर, बहुत सलीक़े से,", "who": "", "voice": "narrator", "diary": false}, {"start": 502.23, "end": 504.62, "text": "उसी तरह, जैसे वो सब कुछ करती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 505.07, "end": 507.76, "text": "उसने ठीक तीन सेकंड के लिए हाथ जोड़े।", "who": "", "voice": "narrator", "diary": false}, {"start": 507.76, "end": 513.79, "text": "फिर वो अपना लॉजिक वाला चेहरा लगाकर हमारे पास वापस आ गई, और क्षितिज और मुझे अचानक,", "who": "", "voice": "narrator", "diary": false}, {"start": 513.79, "end": 518.64, "text": "प्रेशर कुकर की शक्ल वाली एक घंटी में बहुत ज़्यादा दिलचस्पी हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 519.09, "end": 521.21, "text": "गब्बर ने भी कुछ नहीं लिखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 521.21, "end": 524.07, "text": "वो देर तक, अपनी टोपी हाथों में लिए,", "who": "", "voice": "narrator", "diary": false}, {"start": 524.07, "end": 527.34, "text": "देवता के सामने खड़े रहे, होंठ हिलते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 527.34, "end": 530.12, "text": "जब वो वापस आए, उनकी आँखें लाल थीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 530.12, "end": 534.36, "text": "और उन्होंने मुझे बताया, कि ये अगरबत्ती की वजह से है।", "who": "", "voice": "narrator", "diary": false}, {"start": 535.86, "end": 536.69, "text": "अच्छा फ़ॉर्मैट है।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 536.89, "end": 538.47, "text": "मेरे पीछे से एक आवाज़ आई।", "who": "", "voice": "narrator", "diary": false}, {"start": 538.67, "end": 542.17, "text": "बस, काइंडली डू द नीडफ़ुल, थोड़ा सरकारी लगता है।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 542.62, "end": 546.41, "text": "एक बूढ़े आदमी रेलिंग पर मेरे बग़ल में खड़े थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 546.41, "end": 550.87, "text": "मेरी अर्ज़ी के पास पीतल की एक छोटी सी घंटी बाँधते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 550.87, "end": 556.39, "text": "लंबे, सीधी कमर, फ़ौजी सटीकता से तराशी हुई सफ़ेद मूँछ, एक ट्वीड कैप,", "who": "", "voice": "narrator", "diary": false}, {"start": 556.39, "end": 561.01, "text": "और एक छड़ी, जिसकी उन्हें साफ़ तौर पर कोई ज़रूरत नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 561.46, "end": 562.34, "text": "मन्नत पूरी हुई?", "who": "", "voice": "narrator", "diary": false}, {"start": 562.54, "end": 565.02, "text": "मैंने घंटी की तरफ़ इशारा करते हुए उनसे पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 565.47, "end": 567.28, "text": "पोते का एडमिशन।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 567.28, "end": 568.36, "text": "आई-आई-टी।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 568.56, "end": 572.35, "text": "उन्होंने घंटी को हल्का सा झटका दिया, कि वो बज उठी।", "who": "", "voice": "narrator", "diary": false}, {"start": 572.55, "end": 573.69, "text": "गोलू देवता ने सुना।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 573.69, "end": 575.32, "text": "अब मैं भी कुछ सुन लेता हूँ।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 575.52, "end": 577.4, "text": "उन्होंने मेरी अर्ज़ी की तरफ़ सिर हिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 577.6, "end": 580.11, "text": "माफ़ करना, मैं पढ़ रहा था।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 580.11, "end": 581.17, "text": "पुरानी आदत।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 581.37, "end": 583.39, "text": "उनकी भौंहें ज़रा सी ऊपर उठीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 583.59, "end": 585.99, "text": "मिसिंग न्यूक्लियर डिवाइस।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 586.44, "end": 588.99, "text": "उनका नाम भूपाल सिंह धामी था।", "who": "", "voice": "narrator", "diary": false}, {"start": 588.99, "end": 593.1, "text": "रिटायर्ड कमांडेंट, इंडो-तिब्बतन बॉर्डर पुलिस।", "who": "", "voice": "narrator", "diary": false}, {"start": 593.1, "end": 596.84, "text": "कुमाऊँ और गढ़वाल की सरहदों पर चौंतीस साल।", "who": "", "voice": "narrator", "diary": false}, {"start": 597.29, "end": 601.47, "text": "हम मंदिर की सीढ़ियों पर बैठे, और मैंने उन्हें सब कुछ बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 601.47, "end": 607.07, "text": "शाओनी ने उन्हें अपने फ़ोन पर ड्रोन के फ़्रेम्स दिखाए: औली के ऊपर छुपा हुआ कैंप,", "who": "", "voice": "narrator", "diary": false}, {"start": 607.07, "end": 609.56, "text": "रडार, रेडिएशन सिम्बल वाला ग्रे केस।", "who": "", "voice": "narrator", "diary": false}, {"start": 609.56, "end": 611.69, "text": "क्षितिज ने उन्हें डायरी दिखाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 612.14, "end": 614.33, "text": "उन्होंने बिना टोके सुना, उसी तरह,", "who": "", "voice": "narrator", "diary": false}, {"start": 614.33, "end": 616.52, "text": "जैसे इंस्पेक्टर बिष्ट ने सुना था।", "who": "", "voice": "narrator", "diary": false}, {"start": 616.52, "end": 618.52, "text": "लेकिन आख़िर में, वो हँसे नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 618.97, "end": 623.37, "text": "उन्नीस सौ पैंसठ की बात, सब जानते हैं, जो ऊपर रहे हैं।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 623.57, "end": 625.0, "text": "उन्होंने मुझसे धीरे से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 625.2, "end": 626.61, "text": "हम लोग बात नहीं करते।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 626.61, "end": 627.68, "text": "पर सब जानते हैं।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 627.88, "end": 630.24, "text": "वो देर तक ड्रोन के फ़्रेम को देखते रहे।", "who": "", "voice": "narrator", "diary": false}, {"start": 630.44, "end": 632.68, "text": "ये केस मज़ाक़ नहीं है, बेटा।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 632.68, "end": 634.84, "text": "ये असली शील्डिंग कंटेनर है।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 635.29, "end": 636.72, "text": "शाओनी उनकी तरफ़ झुकी।", "who": "", "voice": "narrator", "diary": false}, {"start": 636.92, "end": 637.7, "text": "आप मदद करेंगे?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 638.15, "end": 639.91, "text": "मैं रिटायर्ड हूँ, बेटी।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 639.91, "end": 643.8, "text": "मेरे पास अब सिर्फ़ एक फ़ोन है, और कुछ पुराने दोस्त।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 644.0, "end": 647.28, "text": "उन्होंने अपनी छाती वाली जेब में रखे फ़ोन को थपथपाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 647.48, "end": 650.2, "text": "पर पुराने दोस्त काफ़ी होते हैं।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 650.2, "end": 650.81, "text": "चुपचाप।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 650.81, "end": 651.87, "text": "सीधे ऊपर तक।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 652.07, "end": 653.03, "text": "वो खड़े हो गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 653.23, "end": 654.13, "text": "मुझे दो दिन दो।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 654.58, "end": 656.21, "text": "मैं उन्हें चूम सकता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 656.21, "end": 659.88, "text": "मैंने नहीं चूमा, क्योंकि वो एक रिटायर्ड कमांडेंट थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 659.88, "end": 661.79, "text": "और मुझे अपनी जान प्यारी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 663.29, "end": 666.0, "text": "ठीक तभी, गोलू रास्ते से ऊपर आया।", "who": "", "voice": "narrator", "diary": false}, {"start": 666.45, "end": 668.13, "text": "कोई रिंग लाइट नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 668.13, "end": 669.73, "text": "कोई फ़ोन ऊपर नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 669.73, "end": 673.44, "text": "वो घंटियों के बीच से सीधा वहाँ तक चला आया,", "who": "", "voice": "narrator", "diary": false}, {"start": 673.44, "end": 678.3, "text": "जहाँ हम बैठे थे, मेरे सामने रुका, और सिर्फ़ मुझसे बोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 678.75, "end": 679.71, "text": "प्रोफ़ेसर साहब।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 679.71, "end": 681.12, "text": "मुझे आपसे बात करनी है।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 681.82, "end": 683.41, "text": "और क्षितिज खड़ा हो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 684.11, "end": 687.7, "text": "एक बार, जब वो बारह साल का था, और डायरी नई थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 687.7, "end": 691.54, "text": "मैंने उससे पूछा था, कि वो सब कुछ लिखता क्यों है।", "who": "", "voice": "narrator", "diary": false}, {"start": 691.54, "end": 694.57, "text": "जो लोग नहीं सुनते, उनके लिए लिखता हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 694.57, "end": 696.89, "text": "बाद में प्रूफ़ चाहिए होता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 696.89, "end": 699.52, "text": "दस दिनों से वो प्रूफ़ लिख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 699.52, "end": 700.8, "text": "हर लाइन सटीक थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 700.8, "end": 702.16, "text": "हर तारीख़ सही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 702.16, "end": 708.78, "text": "उसने केस वैसे बनाया था, जैसे एक अच्छा स्टूडेंट अपना जवाब बनाता है, पॉइंट-बाय-पॉइंट,", "who": "", "voice": "narrator", "diary": false}, {"start": 708.78, "end": 713.89, "text": "और आख़िरकार, यहाँ वो पल था, जिसकी तरफ़ वो लिखता आ रहा था: वो पल,", "who": "", "voice": "narrator", "diary": false}, {"start": 713.89, "end": 716.13, "text": "जब लोगों को सुनना ही पड़ेगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 716.58, "end": 720.1, "text": "मैंने क्षितिज को पहले कभी ग़ुस्से में नहीं देखा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 720.1, "end": 721.48, "text": "वो चिल्लाता नहीं है।", "who": "", "voice": "narrator", "diary": false}, {"start": 721.48, "end": 726.58, "text": "उसने अपनी डायरी खोली, और एकदम सधी हुई आवाज़ में, गोलू के ख़िलाफ़ केस पढ़ा,", "who": "", "voice": "narrator", "diary": false}, {"start": 726.58, "end": 728.86, "text": "पन्ना-दर-पन्ना, किसी वकील की तरह,", "who": "", "voice": "narrator", "diary": false}, {"start": 728.86, "end": 731.62, "text": "हर लाइन के बाद उसकी तरफ़ नज़र उठाते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 732.07, "end": 732.58, "text": "डे वन।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 732.58, "end": 736.1, "text": "तुम स्पून्स गिरने से पहले कॉरिडोर में थे।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 736.1, "end": 736.88, "text": "कैमरा ऑन।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 736.88, "end": 737.39, "text": "डे टू।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 737.39, "end": 741.08, "text": "एन-डी-पैंसठ का कमेंट, तुम्हारे लाइव पे आया।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 741.08, "end": 741.85, "text": "डे फ़ाइव।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 741.85, "end": 744.09, "text": "तुम्हारी गाड़ी नीचे से आई,", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 744.09, "end": 747.69, "text": "उसी लाल मिट्टी के साथ, जहाँ मुझे ले गए थे।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 747.69, "end": 748.46, "text": "डे सिक्स।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 748.46, "end": 752.84, "text": "एक बूढ़ी औरत ने तुम्हें गौरव बुलाया, और तुम भाग गए।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 752.84, "end": 756.96, "text": "उसी रात रोहन को पता चल गया, हम द्रोणागिरी गए थे।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 756.96, "end": 757.65, "text": "डे सेवन।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 757.65, "end": 762.37, "text": "तुम्हारा ड्रोन ख़ुद रोहन के कैंप पे गया, और तुम भाग गए।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 762.37, "end": 763.05, "text": "डे नाइन।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 763.05, "end": 764.43, "text": "तुम जागर में थे।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 764.43, "end": 767.26, "text": "सुबह रोहन को पता था, हम वहाँ हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 767.26, "end": 768.63, "text": "और तुम ग़ायब थे।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 769.08, "end": 773.12, "text": "दिन-ब-दिन, उसने सब सामने रख दिया: कैमरा,", "who": "", "voice": "narrator", "diary": false}, {"start": 773.12, "end": 777.26, "text": "कमेंट, लाल मिट्टी, गौरव नाम, ड्रोन, जागर।", "who": "", "voice": "narrator", "diary": false}, {"start": 777.96, "end": 779.0, "text": "उसने डायरी बंद की।", "who": "", "voice": "narrator", "diary": false}, {"start": 779.7, "end": 780.57, "text": "तुम कौन हो?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 781.02, "end": 783.42, "text": "गोलू ने उसे जवाब नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 783.42, "end": 785.37, "text": "उसका जबड़ा कसा हुआ था।", "who": "", "voice": "narrator", "diary": false}, {"start": 785.37, "end": 790.26, "text": "उसकी आँखें फिर से गीली थीं, वैसे ही, जैसे जागर में थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 790.71, "end": 792.32, "text": "मैं उसके साथ नहीं हूँ।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 792.52, "end": 794.28, "text": "उसने आख़िरकार कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 794.28, "end": 795.07, "text": "बस इतना।", "who": "", "voice": "narrator", "diary": false}, {"start": 795.07, "end": 796.54, "text": "कोई सफ़ाई नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 796.54, "end": 797.91, "text": "कोई बचाव नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 797.91, "end": 798.7, "text": "बस इतना।", "who": "", "voice": "narrator", "diary": false}, {"start": 799.15, "end": 800.04, "text": "तो फिर किसके साथ हो?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 800.74, "end": 801.52, "text": "ख़ामोशी।", "who": "", "voice": "narrator", "diary": false}, {"start": 802.22, "end": 802.62, "text": "जाओ।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 802.82, "end": 803.68, "text": "क्षितिज ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 803.88, "end": 804.65, "text": "प्लीज़।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 804.65, "end": 805.41, "text": "बस जाओ।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 805.86, "end": 810.17, "text": "और मैंने, मुझे इस पर गर्व नहीं है, मैंने सिर हिला दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 810.62, "end": 813.25, "text": "शाओनी अकेली थी, जिसने नहीं हिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 813.7, "end": 814.09, "text": "रुको।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 814.29, "end": 814.86, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 814.86, "end": 818.39, "text": "उसने ये पहले गोलू से कहा, और फिर अपने भाई की तरफ़ मुड़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 818.59, "end": 819.02, "text": "लॉजिक।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 819.02, "end": 822.92, "text": "रोहन का मैसेज आया: इजा जी का खाना बहुत तारीफ़ लायक़ है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 822.92, "end": 824.19, "text": "खाना कब खाया हमने?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 824.19, "end": 824.83, "text": "कल दोपहर।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 824.83, "end": 826.96, "text": "गोलू कल दोपहर वहाँ था ही नहीं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 826.96, "end": 828.59, "text": "वो रात को जागर में आया।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 828.59, "end": 831.85, "text": "जिसने रोहन को बताया, उसने हमें खाना खाते देखा,", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 831.85, "end": 835.54, "text": "या किसी ने उसे फ़ोन पे बताया, कि हम खाना खा रहे हैं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 836.24, "end": 837.5, "text": "फिर वो गब्बर की तरफ़ मुड़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 838.2, "end": 838.98, "text": "गब्बर भैया।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 838.98, "end": 841.34, "text": "कल दोपहर आपने किसको फ़ोन किया था?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 841.79, "end": 843.27, "text": "गब्बर ने मुँह खोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 843.27, "end": 844.2, "text": "और बंद किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 844.2, "end": 846.31, "text": "और ज़मीन की तरफ़ देखने लगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 846.76, "end": 849.38, "text": "मैंने उन्हें याद करते हुए देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 849.38, "end": 849.8, "text": "आँगन।", "who": "", "voice": "narrator", "diary": false}, {"start": 849.8, "end": 850.22, "text": "फ़ोन।", "who": "", "voice": "narrator", "diary": false}, {"start": 850.22, "end": 853.51, "text": "हाँ, खाना खा रहे हैं, भट्ट की चुड़कानी।", "who": "", "voice": "narrator", "diary": false}, {"start": 853.51, "end": 859.59, "text": "मैंने वो ख़याल आते हुए देखा, और मैंने उन्हें उसे उठाते हुए देखा, उस तरह,", "who": "", "voice": "narrator", "diary": false}, {"start": 859.59, "end": 863.73, "text": "जैसे आप किसी बच्चे के जूते से बिच्छू निकालते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 863.73, "end": 866.68, "text": "और उसे जितनी दूर हो सके, फेंक दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 866.68, "end": 867.1, "text": "महेश?", "who": "", "voice": "narrator", "diary": false}, {"start": 867.1, "end": 869.22, "text": "महेश, जो साइकिल चलाता था?", "who": "", "voice": "narrator", "diary": false}, {"start": 869.22, "end": 869.64, "text": "नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 869.64, "end": 870.65, "text": "मुमकिन नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 870.65, "end": 871.49, "text": "महेश नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 871.94, "end": 873.84, "text": "उन्होंने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 873.84, "end": 877.3, "text": "और वो ख़ामोशी, मुझे लगता है, वो चीज़ है,", "who": "", "voice": "narrator", "diary": false}, {"start": 877.3, "end": 882.82, "text": "जिस पर गब्बर सिंह नेगी को अपनी पूरी ज़िंदगी में सबसे कम गर्व है।", "who": "", "voice": "narrator", "diary": false}, {"start": 883.27, "end": 889.95, "text": "लेकिन क्षितिज पहले ही मुँह फेर चुका था, और मैं पहले ही सिर हिला चुका था, और गोलू,", "who": "", "voice": "narrator", "diary": false}, {"start": 889.95, "end": 894.73, "text": "दस हज़ार घंटियों और इंसाफ़ की हज़ार अर्ज़ियों के बीच खड़ा,", "who": "", "voice": "narrator", "diary": false}, {"start": 894.73, "end": 898.94, "text": "हम पर एक आख़िरी नज़र डालकर, रास्ते से नीचे चला गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 898.94, "end": 901.16, "text": "उसने पीछे मुड़कर नहीं देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 901.61, "end": 902.49, "text": "ग़लती कर रहे हो।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 902.69, "end": 906.89, "text": "शाओनी ने धीरे से, अपने भाई से और मुझसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 907.09, "end": 907.57, "text": "दोनों।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 908.02, "end": 910.18, "text": "हम में से किसी ने उसे जवाब नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 910.63, "end": 911.43, "text": "वो सही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 911.43, "end": 918.55, "text": "मैं आपको अभी बता देता हूँ, क्योंकि मैं नैरेटर हूँ, और मुझे इजाज़त है: वो पूरी तरह सही थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 918.55, "end": 921.35, "text": "और मुझे ये मानने में, दो और चैप्टर,", "who": "", "voice": "narrator", "diary": false}, {"start": 921.35, "end": 924.79, "text": "और एक भुतहा बंगले में एक बहुत बुरी रात लगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 926.29, "end": 929.17, "text": "हमने मंदिर के नीचे एक ढाबे पर लंच किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 929.17, "end": 932.58, "text": "क्षितिज के लिए बाल मिठाई, जिसे उसकी ज़रूरत थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 932.58, "end": 934.28, "text": "बाक़ी सबके लिए ख़ामोशी।", "who": "", "voice": "narrator", "diary": false}, {"start": 934.73, "end": 937.19, "text": "और फिर मेरा फ़ोन बज़ करने लगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 937.19, "end": 938.17, "text": "और शाओनी का।", "who": "", "voice": "narrator", "diary": false}, {"start": 938.17, "end": 939.32, "text": "और क्षितिज का।", "who": "", "voice": "narrator", "diary": false}, {"start": 939.32, "end": 940.3, "text": "और गब्बर का।", "who": "", "voice": "narrator", "diary": false}, {"start": 940.3, "end": 942.43, "text": "सब एक साथ, घंटियों की तरह।", "who": "", "voice": "narrator", "diary": false}, {"start": 942.88, "end": 945.19, "text": "क्षितिज वहाँ सबसे पहले पहुँचा।", "who": "", "voice": "narrator", "diary": false}, {"start": 945.19, "end": 949.41, "text": "उसने बिना एक शब्द कहे, अपनी स्क्रीन हमारी तरफ़ घुमा दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 949.86, "end": 950.9, "text": "एक न्यूज़ ऐप।", "who": "", "voice": "narrator", "diary": false}, {"start": 950.9, "end": 952.02, "text": "एक रीजनल चैनल।", "who": "", "voice": "narrator", "diary": false}, {"start": 952.02, "end": 954.58, "text": "बड़े लाल अक्षरों में एक हेडलाइन:", "who": "", "voice": "narrator", "diary": false}, {"start": 955.03, "end": 959.3, "text": "टूरिस्ट्स ने ट्रेकिंग फ़र्म से बेशक़ीमती एक्सपीडिशन डॉक्यूमेंट्स चुराए।", "who": "", "voice": "narrator", "diary": false}, {"start": 959.3, "end": 960.86, "text": "पुलिस ने लुकआउट जारी किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 961.31, "end": 966.43, "text": "और उसके नीचे, एक फ़ोटो: धुँधली, किसी सिक्योरिटी कैमरे से।", "who": "", "voice": "narrator", "diary": false}, {"start": 966.43, "end": 967.6, "text": "सवॉय की लॉबी।", "who": "", "voice": "narrator", "diary": false}, {"start": 967.6, "end": 972.81, "text": "मैं, शाओनी और क्षितिज, चेक-आउट करते हुए, मेरा बैग कंधे पर।", "who": "", "voice": "narrator", "diary": false}, {"start": 973.26, "end": 974.26, "text": "ख़बर छोटी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 974.26, "end": 977.63, "text": "समिट सीक्रेट्स, एक प्रतिष्ठित एडवेंचर कंपनी,", "who": "", "voice": "narrator", "diary": false}, {"start": 977.63, "end": 980.47, "text": "ने देहरादून में एफ़-आई-आर दर्ज की थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 980.47, "end": 986.53, "text": "एक तथाकथित प्रोफ़ेसर, और उसके दो साथियों ने, उसके फ़ाउंडर, मिस्टर रोहन सहगल से,", "who": "", "voice": "narrator", "diary": false}, {"start": 986.53, "end": 991.44, "text": "गोपनीय सर्वे डॉक्यूमेंट्स और सामान चुराया था, और माना जा रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 991.44, "end": 995.35, "text": "कि वो कुमाऊँ में एक सफ़ेद एस-यू-वी में घूम रहे हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 995.35, "end": 998.57, "text": "जनता से अनुरोध था, कि पुलिस को सूचित करें।", "who": "", "voice": "narrator", "diary": false}, {"start": 999.02, "end": 1000.11, "text": "फिर एक और ऐप।", "who": "", "voice": "narrator", "diary": false}, {"start": 1000.11, "end": 1000.95, "text": "फिर एक और।", "who": "", "voice": "narrator", "diary": false}, {"start": 1000.95, "end": 1008.0, "text": "फिर मेरे कॉलेज के स्टाफ़ ग्रुप से एक व्हाट्सऐप फ़ॉरवर्ड, सत्रह हैरान इमोजीज़ के साथ,", "who": "", "voice": "narrator", "diary": false}, {"start": 1008.0, "end": 1013.12, "text": "और हेड ऑफ़ डिपार्टमेंट का एक मैसेज, जिसमें बस लिखा था: पार्थ?", "who": "", "voice": "narrator", "diary": false}, {"start": 1013.57, "end": 1015.65, "text": "मैंने अपना फ़ोन मेज़ पर उल्टा रख दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1016.1, "end": 1016.57, "text": "तो।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 1016.77, "end": 1018.33, "text": "क्षितिज ने धीरे से कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1018.53, "end": 1019.66, "text": "अब पुलिस भी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 1020.11, "end": 1022.21, "text": "ढाबे के बाहर, एक पुलिस जीप,", "who": "", "voice": "narrator", "diary": false}, {"start": 1022.21, "end": 1025.55, "text": "मंदिर की तरफ़ ऊपर जाती हुई, धीरे से गुज़री।", "who": "", "voice": "narrator", "diary": false}, {"start": 1025.55, "end": 1029.9, "text": "पैसेंजर सीट पर बैठे कॉन्स्टेबल ने धूप में खड़ी बसंती को,", "who": "", "voice": "narrator", "diary": false}, {"start": 1029.9, "end": 1032.93, "text": "ज़रूरत से एक सेकंड ज़्यादा देर तक देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1033.38, "end": 1037.3, "text": "ऊपर झुरमुट में, दस हज़ार घंटियाँ हवा में हिलीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 1037.3, "end": 1038.97, "text": "सब एक साथ बोलती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1039.42, "end": 1044.6, "text": "मुझे उम्मीद थी, कि कम से कम उनमें से एक, हमारे लिए बोल रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1045.05, "end": 1046.71, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1046.71, "end": 1047.96, "text": "डे इलेवन, चितई।", "who": "", "voice": "narrator", "diary": true}, {"start": 1048.41, "end": 1050.24, "text": "इजा जी का मायका, जोहार।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1050.24, "end": 1053.26, "text": "उनके मौसा थे कुंदन सिंह, तीसरे चरवाहे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1053.26, "end": 1054.22, "text": "वो नहीं रहे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1054.22, "end": 1056.36, "text": "उनके बेटे की विधवा, धना जी,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1056.36, "end": 1059.31, "text": "सर्दियाँ गंगोलीहाट के पास बिताती हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1059.31, "end": 1062.65, "text": "कुंदन का सामान, जोहार के पुराने घर में है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1062.65, "end": 1064.16, "text": "कोई हाथ नहीं लगाता।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1064.61, "end": 1066.76, "text": "राजुला जोहार की थी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1066.76, "end": 1069.7, "text": "राजुला के देश, यानी जोहार।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1069.7, "end": 1070.61, "text": "सॉल्व्ड।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1071.06, "end": 1073.69, "text": "गोलू देवता: अर्ज़ियाँ और घंटियाँ।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1073.69, "end": 1075.37, "text": "पार्थ भाई ने एक लिखी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1075.37, "end": 1076.49, "text": "फ़ॉर्मैट: सही।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1076.49, "end": 1080.73, "text": "काइंडली डू द नीडफ़ुल: कमांडेंट कहते हैं, बहुत सरकारी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1080.73, "end": 1085.44, "text": "दीदी ने कहा, नो डेटा, नो एस-एल-ए, और फिर एक लाल धागा बाँधा,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1085.44, "end": 1088.16, "text": "जब उन्हें लगा कि कोई नहीं देख रहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1088.16, "end": 1090.4, "text": "गब्बर भैया की आँखें लाल थीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1090.4, "end": 1091.12, "text": "अगरबत्ती।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1091.57, "end": 1095.41, "text": "कमांडेंट, रिटायर्ड, भूपाल सिंह धामी, हम पर यक़ीन करते हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1095.41, "end": 1097.47, "text": "कहते हैं, केस असली शील्डिंग है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1097.47, "end": 1098.33, "text": "दो दिन चाहिए।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1098.78, "end": 1100.56, "text": "मैंने गोलू को निकाल दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1100.56, "end": 1102.85, "text": "उसने कहा, मैं उसके साथ नहीं हूँ।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1102.85, "end": 1104.35, "text": "उसने और कुछ नहीं कहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1104.35, "end": 1106.35, "text": "दीदी कहती हैं, मैं ग़लत हूँ।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1106.35, "end": 1110.42, "text": "दीदी का लॉजिक: आर. के मैसेज में इजा जी के खाने की बात थी,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1110.42, "end": 1110.92, "text": "लंच की।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1110.92, "end": 1112.7, "text": "गोलू लंच पर वहाँ नहीं था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1112.7, "end": 1115.35, "text": "गब्बर भैया ने लंच पर किसको फ़ोन किया?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1115.35, "end": 1117.06, "text": "उन्होंने जवाब नहीं दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1117.51, "end": 1119.11, "text": "हम न्यूज़ पर हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1119.11, "end": 1119.86, "text": "वॉन्टेड।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1119.86, "end": 1121.56, "text": "तथाकथित प्रोफ़ेसर।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1121.56, "end": 1125.52, "text": "पार्थ भाई के एच-ओ-डी ने मैसेज किया, पार्थ?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1125.52, "end": 1128.15, "text": "पार्थ भाई ने जवाब नहीं दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1128.15, "end": 1132.11, "text": "ये इस डायरी का, दूसरा सबसे डरावना क्लू है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 17.16, "bed": "caper"}, {"at": 30.17, "bed": "morning"}, {"at": 115.94, "bed": "discovery"}, {"at": 184.13, "bed": "drive"}, {"at": 201.24, "bed": "bells"}, {"at": 327.29, "bed": "petition"}, {"at": 390.11, "bed": "receipt"}, {"at": 452.87, "bed": "bells"}, {"at": 480.59, "bed": "tender"}, {"at": 534.66, "bed": "bells"}, {"at": 596.09, "bed": "suspense"}, {"at": 634.09, "bed": "heroic"}, {"at": 662.09, "bed": "suspicion"}, {"at": 715.38, "bed": "threat"}, {"at": 812.5, "bed": "plan"}, {"at": 840.59, "bed": "sinking"}, {"at": 925.09, "bed": "dhaba"}, {"at": 941.68, "bed": "tension"}, {"at": 1018.91, "bed": "threat"}, {"at": 1032.18, "bed": "bells"}, {"at": 1043.85, "bed": "diary"}, {"at": 1043.85, "bed": "diary"}], "hits": [{"at": 88.11, "fx": "skid"}, {"at": 92.88, "fx": "sting"}, {"at": 173.35, "fx": "page"}, {"at": 183.2, "fx": "sting"}, {"at": 217.6, "fx": "bell"}, {"at": 565.32, "fx": "chime"}, {"at": 681.67, "fx": "sting_light"}, {"at": 777.81, "fx": "page"}, {"at": 838.05, "fx": "sting"}, {"at": 934.58, "fx": "ping"}, {"at": 954.88, "fx": "sting"}, {"at": 1013.42, "fx": "thud"}, {"at": 1019.96, "fx": "suv"}, {"at": 1098.63, "fx": "sting_light"}, {"at": 1117.36, "fx": "sting"}], "next": {"label": "एपिसोड 11", "en": "No Phones in the Underworld", "hook": "फूलों का एक ठेला, एक पुराना राज़, और धरती के नब्बे फ़ुट नीचे एक गुफा, जहाँ फ़ोन नहीं चलते।"}};
